java.util.Arrays.fill(dp, unreachable); dp[0] = 0;
for (int s = 1; s <= amount; s++) {
    for (int c : new int[]{2}) {
        if (s >= c && dp[s-c] != unreachable)
            dp[s] = Math.min(dp[s], dp[s-c] + 1);
